  int conteo;

  if(ultima_estruct != NULL)
    escribe_entero(ultima_estruct + EST_SIG, sig_tipo);
  ultima_estruct = sig_tipo;
  if(lista_estruct == NULL)
    lista_estruct = sig_tipo;
  conteo = 0;
