/*
** Analiza una expresión, y genera el codigo.
*/
unsigned char *expresion()
{
  struct nodo *origen;
  unsigned char *tipo;

  origen = ultimo_nodo;
  tipo = almacena_expresion(SI);
  evalua_arbol(NO);
  libera_arbol(ultimo_nodo);
  ultimo_nodo = origen;
  return tipo;
