And the new version:
void s_break()
{
  /* Ve si hay un bucle abierto */
  if (ultimo_bucle == NULL) {
    error("No loops open");
    return;                         /* No */
  }
  desp_pila(ultimo_bucle->pila);    /* Si, arregla la pila */
  salto(ultimo_bucle->fin);         /* Salta a la etiqueta de salida */
